import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        boolean[] setA = new boolean[10];
        for (int i = 0; i < n; i++) {
            setA[scanner.nextInt()] = true;
        }

        boolean[] setB = new boolean[10];
        for (int i = 0; i < m; i++) {
            setB[scanner.nextInt()] = true;
        }

        // Check for common digit (single digit answer)
        int minCommon = 10;
        for (int d = 1; d <= 9; d++) {
            if (setA[d] && setB[d]) {
                minCommon = d;
                break;
            }
        }

        if (minCommon != 10) {
            System.out.println(minCommon);
            return;
        }

        // Find minimum digits in each set
        int minA = 10, minB = 10;
        for (int d = 1; d <= 9; d++) {
            if (setA[d]) minA = Math.min(minA, d);
            if (setB[d]) minB = Math.min(minB, d);
        }

        // Form two-digit numbers and take minimum
        int candidate1 = minA * 10 + minB;
        int candidate2 = minB * 10 + minA;
        System.out.println(Math.min(candidate1, candidate2));
    }
}
